 @Bean TaskPlanDraftDeployment taskPlanDraftDeployment(@Value("${medical.professional-runtime.plan-draft.deployment-file}")Path file,@Value("${medical.professional-runtime.plan-draft.deployment-owner}")String owner,@Value("${medical.professional-runtime.plan-draft.deployment-sha256}")String hash,@Value("${medical.professional-runtime.plan-draft.maximum-deployment-bytes}")int maximum)throws Exception{return readDeployment(file,owner,hash,maximum);}
    static TaskPlanDraftDeployment readDeployment(Path file,String owner,String expected,int maximum)throws Exception {
        if(file==null||!file.isAbsolute()||!file.normalize().equals(file)||owner==null||owner.isBlank()||maximum<1||maximum>2097152||!file.toRealPath().equals(file))throw new IllegalArgumentException("PINNED_PROFESSIONAL_DEPLOYMENT_REQUIRED");
        var principal=file.getFileSystem().getUserPrincipalLookupService().lookupPrincipalByName(owner);
        var before=Files.readAttributes(file,BasicFileAttributes.class,LinkOption.NOFOLLOW_LINKS);
        if(!before.isRegularFile()||before.size()<1||before.size()>maximum||!Files.getOwner(file,LinkOption.NOFOLLOW_LINKS).equals(principal))throw new IllegalArgumentException("OWNED_PROFESSIONAL_DEPLOYMENT_REQUIRED");
        var permissions=Files.getPosixFilePermissions(file,LinkOption.NOFOLLOW_LINKS);if(!Set.of(PosixFilePermissions.fromString("r--------"),PosixFilePermissions.fromString("rw-------")).contains(permissions))throw new IllegalArgumentException("PRIVATE_PROFESSIONAL_DEPLOYMENT_REQUIRED");
        byte[] bytes;try(var input=Files.newInputStream(file,LinkOption.NOFOLLOW_LINKS)){bytes=input.readNBytes(maximum+1);}var after=Files.readAttributes(file,BasicFileAttributes.class,LinkOption.NOFOLLOW_LINKS);
        if(bytes.length!=before.size()||bytes.length>maximum||!Objects.equals(before.fileKey(),after.fileKey())||!before.lastModifiedTime().equals(after.lastModifiedTime())||before.size()!=after.size())throw new IllegalArgumentException("PROFESSIONAL_DEPLOYMENT_CHANGED");
        var json=com.fasterxml.jackson.databind.json.JsonMapper.builder().enable(com.fasterxml.jackson.core.StreamReadFeature.STRICT_DUPLICATE_DETECTION).enable(com.fasterxml.jackson.databind.DeserializationFeature.FAIL_ON_TRAILING_TOKENS).build();
        return new TaskPlanDraftDeployment(json.readTree(bytes),expected);
    }
 @Bean TaskPlanDraftJobs taskPlanDraftJobs(@Qualifier("masterDataSource")DataSource data,PermissionSchema json,TaskPlanDraftSchema schema,RunTokenAuthoritySchema runtime){return new TaskPlanDraftJobs(data,json,schema,runtime);}
 @Bean TaskPlanDraftJobAuthority taskPlanDraftJobAuthority(TaskPlanDraftJobs jobs,TaskPlanDraftSchema schema){return new TaskPlanDraftJobAuthority(jobs,schema);}
 @Bean TaskPlanDraftControlAccess taskPlanDraftControlAccess(@Qualifier("masterDataSource")DataSource data,TenantTransaction tx,@Qualifier("formalRunServiceIdentity")ServiceCertificateIdentity services,PermissionMapper permissions,PermissionAuthority grants,VersionResourceMapper owners,ArtifactRegistryMapper registry,TaskPlanDraftJobs jobs,TaskPlanDraftSchema schema,RunTokenAuthoritySchema runtime,@Value("${medical.professional-runtime.plan-draft.maximum-control-seconds}")long seconds,@Value("${medical.professional-runtime.plan-draft.maximum-dependencies}")int maximum){return new TaskPlanDraftControlAccess(data,tx,services,permissions,grants,owners,registry,jobs,schema,runtime,Duration.ofSeconds(seconds),maximum);}
 @Bean TaskPlanDraftRuntimeAuthority taskPlanDraftRuntimeAuthority(@Qualifier("masterDataSource")DataSource data,TaskPlanDraftJobs jobs,TaskPlanDraftSchema schema,RunTokenAuthoritySchema tokens,FormalCapabilityIdentityAuthority roles){return new TaskPlanDraftRuntimeAuthority(data,jobs,schema,tokens,roles);}
 @Bean TaskPlanDraftTokenAuthority taskPlanDraftTokenAuthority(@Qualifier("masterDataSource")DataSource data,TaskPlanDraftControlAccess controls,AgentPublicationAuthority publications,AgentExecutionPolicyAuthority policies,TaskPlanDraftAdmission admissions,TaskPlanDraftJobAuthority jobs,TaskPlanDraftJobs ledger,TaskPlanDraftSchema schema,TaskPlanDraftRuntimeAuthority runtime){return new TaskPlanDraftTokenAuthority(data,controls,publications,policies,admissions,jobs,ledger,schema,runtime);}
