 @Bean(name="planDraftObjectTransport") RuntimeObjectTransport planDraftObjectTransport(SourceUploadTransport objects,TaskPlanDraftDeployment deployment,@Value("${medical.professional-runtime.plan-draft.object-directory}")Path directory)throws Exception{return new RuntimeObjectTransport(objects,directory,deployment.maximumBytes());}
 @Bean TaskPlanDraftRuntimeAdapter taskPlanDraftRuntimeAdapter(@Qualifier("masterDataSource")DataSource data,TaskPlanDraftSchema schema,PermissionSchema json,TaskPlanDraftDeployment deployment,@Qualifier("formalRunServiceIdentity")ServiceCertificateIdentity identities,TaskPlanDraftCandidateNormalizer normalizer,TaskPlanDraftProducerAuthority producers){return new TaskPlanDraftRuntimeAdapter(data,schema,json,deployment,identities,normalizer,producers);}
 @Bean TaskPlanDraftSupervisor taskPlanDraftSupervisor(@Qualifier("masterDataSource")DataSource data,PermissionSchema json,@Qualifier("planDraftSupervisorTrust")ServiceCertificateIdentity.TrustSource trust,@Qualifier("planDraftSupervisorTls")ServiceClientTlsStore.ContextSource tls){return new TaskPlanDraftSupervisor(data,json,new ServiceCertificateIdentity(trust),trust,tls);}
 @Bean TaskPlanDraftHostAccess taskPlanDraftHostAccess(TaskPlanDraftControlAccess controls,TaskPlanDraftWorkerAccess workers,TaskPlanDraftRuntimeAuthority authorities,TaskPlanDraftObjectLedger ledger,TaskPlanDraftObjectRegistration registration,@Qualifier("planDraftObjectTransport")RuntimeObjectTransport transport,TaskPlanDraftPackages packages,TaskPlanDraftPromptCompiler compiler,TaskPlanDraftRuntimeAdapter runtime,TaskPlanDraftDeployment deployment,RunTokenAuthority tokens){return new TaskPlanDraftHostAccess(controls,workers,authorities,ledger,registration,transport,packages,compiler,runtime,deployment,tokens);}
