 @Bean TaskPlanDraftLaunchConfiguration taskPlanDraftLaunchConfiguration(@Value("${medical.professional-runtime.plan-draft.launch-revision}")String revision,@Value("${medical.professional-runtime.plan-draft.control-task-queue}")String control,@Value("${medical.professional-runtime.plan-draft.professional-task-queue}")String professional,@Value("${medical.professional-runtime.plan-draft.activity-timeout-millis}")long timeout,@Value("${medical.professional-runtime.plan-draft.heartbeat-timeout-millis}")long heartbeat){return new TaskPlanDraftLaunchConfiguration(revision,control,professional,timeout,heartbeat);}
